<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Award, Dumbbell, Flame, Plus, TrendingUp, Trash2, X } from '@lucide/vue'
import { useAppStore, workoutVolume } from '@/stores/app'
const store=useAppStore();const range=ref(90);const dialog=ref<HTMLDialogElement>();const form=reactive({date:new Date().toISOString().slice(0,10),weight:store.measurements[0]?.weight??0,bodyFat:null as number|null,note:''})
const cutoff=computed(()=>Date.now()-range.value*86400000);const workouts=computed(()=>store.history.filter(w=>range.value===0||new Date(w.startedAt).getTime()>=cutoff.value));const volume=computed(()=>workouts.value.reduce((sum,w)=>sum+workoutVolume(w),0));const reps=computed(()=>workouts.value.reduce((sum,w)=>sum+w.exercises.flatMap(e=>e.sets).filter(s=>s.done).reduce((n,s)=>n+s.reps,0),0));const muscleData=computed(()=>{const counts=new Map<string,number>();for(const w of workouts.value)for(const item of w.exercises){const muscle=store.exerciseList.find(e=>e.id===item.exerciseId)?.muscle??'Other';counts.set(muscle,(counts.get(muscle)??0)+item.sets.filter(s=>s.done).length)}const max=Math.max(...counts.values(),1);return[...counts].sort((a,b)=>b[1]-a[1]).slice(0,6).map(([n,v])=>({n,v:Math.round(v/max*100)}))});const weightPoints=computed(()=>store.measurements.slice().reverse().map((m,i,a)=>{const values=a.map(x=>x.weight),min=Math.min(...values)-1,max=Math.max(...values)+1;return`${a.length===1?350:i/(a.length-1)*700},${230-(m.weight-min)/(max-min)*190}`} ).join(' '))
function add(){if(!form.date||form.weight<=0)return;store.addMeasurement({...form});dialog.value?.close()}
const oldestMeasurement=computed(()=>store.measurements[store.measurements.length-1])
</script>
<template><div class="page"><header class="page-head"><div><span class="eyebrow">PROGRESS, NOT PERFECTION</span><h1>Progress</h1><p>Clear signals from the work you've done.</p></div><select v-model.number="range" class="select"><option :value="30">Last month</option><option :value="90">Last 3 months</option><option :value="180">Last 6 months</option><option :value="0">All time</option></select></header><section class="stat-grid four"><article class="stat-card"><span class="stat-icon coral"><Dumbbell :size="19"/></span><div><strong>{{ workouts.length }}</strong><span>Workouts</span></div><small>Selected range</small></article><article class="stat-card"><span class="stat-icon lime"><TrendingUp :size="19"/></span><div><strong>{{ Math.round(volume/1000) }}k</strong><span>Total volume</span></div><small>{{ store.profile.units }}</small></article><article class="stat-card"><span class="stat-icon purple"><Award :size="19"/></span><div><strong>{{ reps }}</strong><span>Total reps</span></div><small>Completed sets</small></article><article class="stat-card"><span class="stat-icon amber"><Flame :size="19"/></span><div><strong>{{ store.workoutsThisWeek.length }}/{{ store.profile.weeklyGoal }}</strong><span>Weekly goal</span></div><small>Keep moving</small></article></section><section class="progress-grid"><article class="panel chart-panel"><div class="panel-head"><div><span class="eyebrow">BODY WEIGHT</span><h2>Measurement trend</h2></div><button class="btn btn-quiet" @click="dialog?.showModal()"><Plus :size="16"/> Add</button></div><svg viewBox="0 0 700 250" role="img" aria-label="Body weight trend"><polyline :points="weightPoints" fill="none" stroke="#ff5b35" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-axis"><span>{{ oldestMeasurement?.date }}</span><strong>{{ store.measurements[0]?.weight }} {{ store.profile.units }}</strong><span>{{ store.measurements[0]?.date }}</span></div></article><article class="panel muscle-panel"><div class="panel-head"><div><span class="eyebrow">MUSCLE BALANCE</span><h2>Selected range</h2></div></div><div v-for="item in muscleData" :key="item.n" class="muscle-row"><span>{{ item.n }}</span><div><i :style="{width:item.v+'%'}"></i></div><strong>{{ item.v }}%</strong></div><p v-if="!muscleData.length" class="small-empty">Finish a workout to see balance.</p></article></section><section class="measurement-list panel"><div class="panel-head"><div><span class="eyebrow">MEASUREMENTS</span><h2>Recent entries</h2></div></div><div v-for="item in store.measurements" :key="item.id" class="measurement-row"><span><strong>{{ new Date(item.date+'T00:00:00').toLocaleDateString('en',{month:'short',day:'numeric'}) }}</strong><small>{{ item.note||'Body check-in' }}</small></span><strong>{{ item.weight }} {{ store.profile.units }}</strong><span>{{ item.bodyFat?item.bodyFat+'% body fat':'-' }}</span><button class="icon-button" aria-label="Delete measurement" @click="store.deleteMeasurement(item.id)"><Trash2 :size="15"/></button></div></section><dialog ref="dialog" class="form-dialog"><form method="dialog" @submit.prevent="add"><header><div><span class="eyebrow">BODY CHECK-IN</span><h2>Add measurement</h2></div><button type="button" class="icon-button" @click="dialog?.close()"><X/></button></header><label class="field-label">Date<input v-model="form.date" type="date" required/></label><div class="field-pair"><label class="field-label">Weight ({{ store.profile.units }})<input v-model.number="form.weight" type="number" min="1" step="0.1" required/></label><label class="field-label">Body fat %<input v-model.number="form.bodyFat" type="number" min="1" max="70" step="0.1"/></label></div><label class="field-label">Note<input v-model="form.note" maxlength="120" placeholder="Optional note"/></label><button class="btn btn-primary btn-wide" type="submit">Save measurement</button></form></dialog></div></template>
